// Samler installert vs nyeste versjon for Docker-containere (Komodo) mot GitHub-releases.
// Lagrer resultat i workflow static data; webhook "versjoner" leverer det til nettverkskartet.
const KOMODO = 'http://10.0.0.117:9120';
const H = {'X-Api-Key': 'REDACTED_KOMODO_KEY', 'X-Api-Secret': 'REDACTED_KOMODO_SECRET', 'Content-Type': 'application/json'};
const GHTOKEN = 'REDACTED_GITHUB_TOKEN';
const GH = {"pihole/pihole": "pi-hole/docker-pi-hole", "moghtech/komodo-periphery": "moghtech/komodo", "semaphoreui/semaphore": "semaphoreui/semaphore", "gitea/gitea": "go-gitea/gitea", "prom/alertmanager": "prometheus/alertmanager", "prom/prometheus": "prometheus/prometheus", "prom/node-exporter": "prometheus/node_exporter", "grafana/alloy": "grafana/alloy", "emby/embyserver": "MediaBrowser/Emby.Releases", "chrisbenincasa/tunarr": "chrisbenincasa/tunarr", "goauthentik/server": "goauthentik/authentik", "netalertx/netalertx": "netalertx/NetAlertX", "linuxserver/bazarr": "morpheus65535/bazarr", "cleanuparr/cleanuparr": "Cleanuparr/Cleanuparr", "flaresolverr/flaresolverr": "FlareSolverr/FlareSolverr", "gethomepage/homepage": "gethomepage/homepage", "akhilrex/podgrab": "akhilrex/podgrab", "binhex/arch-prowlarr": "Prowlarr/Prowlarr", "binhex/arch-radarr": "Radarr/Radarr", "binhex/arch-sonarr": "Sonarr/Sonarr", "binhex/arch-readarr": "Readarr/Readarr", "seerr-team/seerr": "seerr-team/seerr", "linuxserver/speedtest-tracker": "alexjustesen/speedtest-tracker", "ntop/ntopng": "ntop/ntopng", "jbartlett777/diskspeed": "jbartlett777/DiskSpeed", "alexta69/metube": "alexta69/metube", "germannewsmaker/myspeed": "gnmyt/myspeed", "netboxcommunity/netbox": "netbox-community/netbox", "smallstep/step-ca": "smallstep/certificates", "louislam/uptime-kuma": "louislam/uptime-kuma", "kieraneglin/pinchflat": "kieraneglin/pinchflat", "henrygd/beszel": "henrygd/beszel", "crazymax/diun": "crazy-max/diun", "amir20/dozzle": "amir20/dozzle", "jasongdove/ersatztv": "ErsatzTV/ErsatzTV", "twinproduction/gatus": "TwiN/gatus", "robsmallridge/grovemap": "robsmallridge/grovemap", "linuxserver/healthchecks": "healthchecks/healthchecks", "corentinth/it-tools": "CorentinTh/it-tools", "kopia/kopia": "kopia/kopia", "berriai/litellm": "BerriAI/litellm", "qdrant/qdrant": "qdrant/qdrant", "analogj/scrutiny": "AnalogJ/scrutiny", "vaultwarden/server": "dani-garcia/vaultwarden", "containrrr/watchtower": "containrrr/watchtower", "clickhouse/clickhouse-server": "ClickHouse/ClickHouse", "binhex/arch-deluge": "deluge-torrent/deluge", "gitea": "go-gitea/gitea"};
const SKIP = ['postgres','redis','nginx','alpine','node','ferretdb','mysql','mariadb','komodo-core'];
const komodo = (type, params) => this.helpers.httpRequest({method:'POST', url: KOMODO + '/read', headers: H, body: {type, params}, json: true, timeout: 30000});
const core = img => { let i = img.split('@')[0]; const last = i.split('/').pop(); if (last.includes(':')) i = i.slice(0, i.lastIndexOf(':'));
  for (const p of ['docker.io/library/','docker.io/','lscr.io/','ghcr.io/','docker.gitea.com/']) if (i.startsWith(p)) i = i.slice(p.length); return i.toLowerCase(); };
const tag = img => { const last = img.split('@')[0].split('/').pop(); return last.includes(':') ? last.split(':').slice(1).join(':') : ''; };
const clean = v => String(v || '').trim().replace(/^(v|release-|version-)/, '').replace('-stable', '');
const vkey = v => (v.match(/\d+/g) || []).map(Number);
const cache = {};
const gh = async (repo) => {
  if (repo in cache) return cache[repo];
  const h = {'User-Agent':'homelab-n8n','Accept':'application/vnd.github+json'}; if (GHTOKEN) h.Authorization = 'Bearer ' + GHTOKEN;
  let res = null;
  try { res = clean((await this.helpers.httpRequest({url:`https://api.github.com/repos/${repo}/releases/latest`, headers:h, json:true, timeout:20000})).tag_name); }
  catch (e) { try { const t = await this.helpers.httpRequest({url:`https://api.github.com/repos/${repo}/tags?per_page=1`, headers:h, json:true, timeout:20000}); res = t.length ? clean(t[0].name) : null; } catch (e2) { res = null; } }
  cache[repo] = res; return res;
};
const rows = [];
const servers = await komodo('ListServers', {});
for (const sv of servers) {
  if (sv.info.state !== 'Ok') continue;
  let cs; try { cs = await komodo('ListDockerContainers', {server: sv.id}); } catch (e) { continue; }
  for (const c of cs) {
    if (c.state !== 'running') continue;
    const img = c.image || ''; const k = core(img);
    if (SKIP.includes(k.split('/').pop()) || k.startsWith('sha256')) continue;
    let inst = '';
    try { const ins = await komodo('InspectDockerContainer', {server: sv.id, container: c.name}); const lab = (ins.Config || {}).Labels || {};
      inst = lab['org.opencontainers.image.version'] || lab['build_version'] || ''; if (inst.includes('Linuxserver')) inst = inst.split(' ').pop(); } catch (e) {}
    const t = tag(img);
    if (/\d+\.\d+/.test(t)) inst = t; else if (!/\d/.test(inst || '')) inst = /\d/.test(t) ? t : '';
    inst = clean(inst);
    const repo = GH[k]; const lat = repo ? await gh(repo) : null;
    let status;
    if (!inst || !lat) status = 'ukjent';
    else { const a = vkey(inst), b = vkey(lat); const n = Math.min(a.length, b.length); status = 'ok';
      for (let i = 0; i < n; i++) { if (a[i] > b[i]) break; if (a[i] < b[i]) { status = 'gammel'; break; } } }
    rows.push({server: sv.name, navn: c.name, image: k, installert: inst, nyeste: lat || '', status});
  }
}
const ord = {gammel:0, ukjent:1, ok:2};
rows.sort((x, y) => ord[x.status]-ord[y.status] || x.server.localeCompare(y.server) || x.navn.localeCompare(y.navn));
const d = new Date(Date.now() + 3600*1000);
const out = {generert: d.toISOString().slice(0,16).replace('T',' '), antall: rows.length, rader: rows};
const st = $getWorkflowStaticData('global');
const prev = new Set(st.red || []);
const nowRed = rows.filter(r => r.status === 'gammel').map(r => r.navn + '@' + r.server + ':' + r.nyeste);
const fresh = rows.filter(r => r.status === 'gammel' && !prev.has(r.navn + '@' + r.server + ':' + r.nyeste));
st.data = out; st.red = nowRed;
// Varsler kun om NYE utdaterte (dedupe: samme navn+nyeste varsles én gang)
if (!fresh.length || !prev.size && st.first !== false && (st.first = false) === false && false) return [];
const lines = fresh.slice(0, 15).map(r => `• ${r.navn} (${r.server}): ${r.installert} → ${r.nyeste}`).join('\n');
return [{json: {username: 'Versjonsvakt', text: 'Nye oppdateringer tilgjengelig', attachments: [{title: `${fresh.length} container(e) har ny versjon`, text: lines + (fresh.length > 15 ? `\n…og ${fresh.length-15} til` : '') + '\nOversikt: http://10.0.0.124:3020/ (Versjoner nederst)'}]}}];

// Sammenligner siste Komodo-release på GitHub med versjonen Core kjører.
// Varsler én gang per ny versjon (lagres i workflow static data).
const rel = await this.helpers.httpRequest({ url: 'https://api.github.com/repos/moghtech/komodo/releases/latest', headers: { 'User-Agent': 'homelab-n8n', 'Accept': 'application/vnd.github+json' }, json: true });
const latest = String(rel.tag_name || '').replace(/^v/, '');
const core = String(await this.helpers.httpRequest({ url: 'http://10.0.0.117:9120/version', json: false })).trim().replace(/^v/, '');
const state = $getWorkflowStaticData('global');
if (!latest || !core || latest === core || state.last_notified === latest) return [];
state.last_notified = latest;
return [{ json: { username: 'Komodo', text: 'Ny Komodo-versjon', attachments: [{
  title: `Ny Komodo-versjon v${latest}`,
  text: `Komodo v${latest} er ute (Core kjører v${core}). Slik oppdaterer du: 1) oppgrader Core på CT110, 2) kjør «ct-periphery-update --alle» på en node. Se ACCESS-RUNBOOK «Oppdatere Komodo». ${rel.html_url || ''}`
}] } }];
